using Microsoft.AspNetCore.Mvc;
namespace Sigov.Api.Controllers.V1;
[Route("api/v1/mobile")]public sealed class MobileSyncApiController : ExternalV1Base
{ [HttpPost("sync/pull")] public IActionResult Pull([FromBody]object payload)=>OkEnvelope(new{serverVersion=DateTimeOffset.UtcNow,roteiros=Array.Empty<object>(),tarefas=Array.Empty<object>(),fallback="Offline real exige tabelas campo_*; nada foi fabricado."}); [HttpPost("sync/push")] public IActionResult Push([FromBody]object payload)=>OkEnvelope(new{accepted=false,conflitos=Array.Empty<object>(),fallback="Push preparado para registrar conflitos e auditoria quando sigov.campo_sincronizacao existir."}); [HttpPost("evidencias")] public IActionResult Evidencias([FromBody]object payload)=>OkEnvelope(new{accepted=false,fallback="Evidência só será salva com storage/schema configurados."}); [HttpGet("roteiros")] public IActionResult Roteiros()=>AcceptedFallback("Roteiros mobile"); [HttpGet("tarefas")] public IActionResult Tarefas()=>AcceptedFallback("Tarefas mobile"); }
